# Read in chunks to find all tool call lines
tool_data = {}
for offset in range(3000, 126668, 1000):
    chunk = await CONTEXT.read(offset, 1000)
    for match in re.finditer(r'\[tool (\d+)\] (\w+)', chunk):
        num = int(match.group(1))
        name = match.group(2)
        if num not in tool_data:
            tool_data[num] = name

# Print first 30 tool calls
for i in sorted(tool_data.keys())[:30]:
    print(f"  tool {i}: {tool_data[i]}")
